function createDebouncedSaver(ms) {
  let timer = null;
  const cancel = () => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  };
  const run = (payload) => {
    if (typeof payload === "function") {
      payload();
    } else {
      saveCanvasState(payload);
    }
  };
  return {
    schedule(payload) {
      cancel();
      timer = setTimeout(() => {
        timer = null;
        run(payload);
      }, ms);
    },
    flush(payload) {
      cancel();
      run(payload);
    },
    cancel
  };
}

